#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=5

# PIN-47. Pinch stores nothing in R2, but the Cloudflare token it deploys the
# share-page Worker with can read the other projects' R2 bucket. This wizard
# swaps it for a token that can only deploy the Worker, then retires the old one.
# One-off: delete this file when the ticket is done.

CF_API="https://api.cloudflare.com/client/v4"
CF_TOKENS_URL="https://dash.cloudflare.com/profile/api-tokens"
export GH_REPO="yardenfarag/Recipe_app"
DEPLOY_WORKFLOW="deploy-share-worker.yml"

# cf_get TOKEN PATH prints the API response. The token goes to curl on stdin,
# so it never shows up in the process list.
cf_get() {
  printf 'header = "Authorization: Bearer %s"\n' "$1" \
    | curl -sS --max-time 30 -K - "$CF_API$2" 2>/dev/null || true
}
# cf_ok TOKEN PATH succeeds when Cloudflare answers "success": true.
cf_ok() { cf_get "$1" "$2" | grep -q '"success":[[:space:]]*true'; }
# cf_first_id TOKEN PATH prints the first "id" in the response.
cf_first_id() { cf_get "$1" "$2" | grep -o '"id":"[0-9a-f]\{32\}"' | head -n1 | cut -d'"' -f4; }

# gh_ready succeeds when gh can act on the repo. gh is not logged in on this
# machine, so borrow the token Git Credential Manager already holds.
gh_ready() {
  command -v gh >/dev/null 2>&1 || return 1
  gh auth status >/dev/null 2>&1 && return 0
  local t
  t=$(printf 'protocol=https\nhost=github.com\n\n' \
    | GIT_TERMINAL_PROMPT=0 git credential fill 2>/dev/null | sed -n 's/^password=//p') || true
  [[ -n "$t" ]] || return 1
  export GH_TOKEN="$t"
  gh auth status >/dev/null 2>&1
}

[[ -f "$ENV_FILE" ]] || { echo "Run this from the repo root (no $ENV_FILE here)." >&2; exit 1; }

banner "Pinch: a Cloudflare token that can't reach R2 (PIN-47)"

# ── Stage 1: what can the current token reach? ────────────────────────────
stage "Check the current token"
OLD_CF_TOKEN=$(_existing CLOUDFLARE_API_TOKEN || true)
OLD_CF_TOKEN="${OLD_CF_TOKEN%$'\r'}"
NEW_CF_TOKEN=""
ALREADY_SCOPED=0
CF_ACCOUNT_ID=""

if [[ -z "$OLD_CF_TOKEN" ]]; then
  warn "No CLOUDFLARE_API_TOKEN in $ENV_FILE, so there is nothing local to compare against."
else
  CF_ACCOUNT_ID=$(cf_first_id "$OLD_CF_TOKEN" "/accounts?per_page=1" || true)
fi
if [[ -z "$CF_ACCOUNT_ID" ]]; then
  say "I couldn't read the account ID with the current token."
  open_url "https://dash.cloudflare.com/?to=/:account/workers-and-pages"
  step "On Workers & Pages, copy the Account ID from the right-hand column."
  ask CF_ACCOUNT_ID "Paste the Cloudflare account ID:"
fi

if [[ -n "$OLD_CF_TOKEN" ]] && cf_ok "$OLD_CF_TOKEN" "/accounts/$CF_ACCOUNT_ID/r2/buckets"; then
  warn "The token in $ENV_FILE can list R2 buckets it has no business seeing:"
  cf_get "$OLD_CF_TOKEN" "/accounts/$CF_ACCOUNT_ID/r2/buckets" \
    | grep -o '"name":"[^"]*"' | cut -d'"' -f4 | while read -r b; do note "    $b"; done || true
  say "Pinch only needs it to deploy the share-page Worker. Next: a narrower token."
elif [[ -n "$OLD_CF_TOKEN" ]] && cf_ok "$OLD_CF_TOKEN" "/user/tokens/verify"; then
  say "${GREEN}The token in $ENV_FILE is active and already has no R2 access.${RESET}"
  note "Looks like a re-run. I'll skip creating a token and carry on from GitHub."
  ALREADY_SCOPED=1
  NEW_CF_TOKEN="$OLD_CF_TOKEN"
  OLD_CF_TOKEN=""
else
  warn "The token in $ENV_FILE is missing or no longer valid. We'll make a fresh one."
  OLD_CF_TOKEN=""
fi
pause

# ── Stage 2: create the scoped token ──────────────────────────────────────
stage "Cloudflare: create the Worker-only token"
if (( ALREADY_SCOPED )); then
  say "Already done on an earlier run."
  pause
else
  open_url "$CF_TOKENS_URL"
  step "Click 'Create Token', then 'Use template' next to 'Edit Cloudflare Workers'."
  step "Rename it to: pinch-share-worker-deploy"
  step "Under Permissions, delete every row EXCEPT these five:"
  note "      Account · Workers Scripts   · Edit"
  note "      Account · Account Settings  · Read"
  note "      Zone    · Workers Routes    · Edit"
  note "      User    · User Details      · Read"
  note "      User    · Memberships       · Read"
  step "Make sure 'Workers R2 Storage' is gone. That row is the whole point."
  step "Account Resources: Include → your account."
  step "Zone Resources: Include → Specific zone → pinch-app.io"
  step "'Continue to summary' → 'Create Token' → copy it (shown only once)."
  note "Row names may differ a little from the above. I test the token next either way."
  printf '\n'
  while true; do
    ask_secret NEW_CF_TOKEN "Paste the new token:"
    NEW_CF_TOKEN="${NEW_CF_TOKEN//[[:space:]]/}"
    problem=""
    if [[ -z "$NEW_CF_TOKEN" ]]; then
      problem="nothing was pasted"
    elif [[ "$NEW_CF_TOKEN" == "$OLD_CF_TOKEN" ]]; then
      problem="that is the old token from $ENV_FILE"
    elif ! cf_ok "$NEW_CF_TOKEN" "/user/tokens/verify"; then
      problem="Cloudflare says this token is not valid"
    elif cf_ok "$NEW_CF_TOKEN" "/accounts/$CF_ACCOUNT_ID/r2/buckets"; then
      problem="this token can still list R2 buckets (edit it and remove 'Workers R2 Storage')"
    elif ! cf_ok "$NEW_CF_TOKEN" "/accounts/$CF_ACCOUNT_ID/workers/scripts"; then
      problem="this token can't list Workers (it needs Account · Workers Scripts · Edit)"
    fi
    if [[ -z "$problem" ]]; then
      printf '  %s✓%s valid, can manage Workers, R2 is denied\n' "$GREEN" "$RESET"
      if cf_get "$NEW_CF_TOKEN" "/zones?name=pinch-app.io" | grep -q '"name":"pinch-app.io"'; then
        printf '  %s✓%s can see the pinch-app.io zone\n' "$GREEN" "$RESET"
      else
        warn "It can't see the pinch-app.io zone. The deploy in stage 4 will tell us if that matters."
      fi
      break
    fi
    warn "Not usable: $problem."
    confirm "Fix it in the dashboard and paste again?" || { say "Stopped. Nothing was changed."; exit 1; }
  done
  pause
fi

# ── Stage 3: put the new token where Pinch reads it ───────────────────────
stage "Save the token: .env and GitHub Actions"
if (( ALREADY_SCOPED )); then
  note "$ENV_FILE already holds the scoped token."
else
  write_env CLOUDFLARE_API_TOKEN "$NEW_CF_TOKEN"
fi
GH_OK=0
if gh_ready; then GH_OK=1; fi
set_secret CLOUDFLARE_API_TOKEN "$NEW_CF_TOKEN"   # read by deploy-share-worker.yml
if [[ " ${WRITTEN_SECRET[*]-} " != *" CLOUDFLARE_API_TOKEN "* ]]; then
  GH_OK=0
  say "Set it by hand instead:"
  open_url "https://github.com/$GH_REPO/settings/secrets/actions"
  step "Edit the repository secret CLOUDFLARE_API_TOKEN."
  step "Paste the value of CLOUDFLARE_API_TOKEN from $ENV_FILE and save."
  pause "Press Enter once the secret is updated"
fi
note "CLOUDFLARE_ACCOUNT_ID stays as it is."
pause

# ── Stage 4: prove the real deploy works with it ──────────────────────────
stage "Deploy the share-page Worker with the new token"
say "This runs the normal 'Deploy share page worker' workflow on master."
say "It redeploys the same Worker code, so nothing changes for users."
DEPLOY_OK=0
if (( GH_OK )) && confirm "Start the deploy now and wait for it (a few minutes)?"; then
  if gh workflow run "$DEPLOY_WORKFLOW" --ref master >/dev/null 2>&1; then
    sleep 8
    run_id=$(gh run list --workflow "$DEPLOY_WORKFLOW" --event workflow_dispatch --limit 1 \
      --json databaseId --jq '.[0].databaseId' 2>/dev/null || true)
    if [[ -n "$run_id" ]] && gh run watch "$run_id" --exit-status; then
      DEPLOY_OK=1
      printf '  %s✓%s deploy succeeded with the new token\n' "$GREEN" "$RESET"
    else
      warn "The run failed or couldn't be watched. Check it in the browser:"
      open_url "https://github.com/$GH_REPO/actions/workflows/$DEPLOY_WORKFLOW"
    fi
  else
    warn "Couldn't start the workflow from here."
  fi
fi
if (( ! DEPLOY_OK )); then
  open_url "https://github.com/$GH_REPO/actions/workflows/$DEPLOY_WORKFLOW"
  step "If no run is in progress: 'Run workflow' → branch master → 'Run workflow'."
  step "Wait for the 'deploy' job to go green."
  note "If it fails on an authentication or permission error, the token is missing a row."
  note "Edit the token in Cloudflare (same value keeps working), then re-run the job."
  if confirm "Did the deploy job finish green?"; then DEPLOY_OK=1; fi
fi
if (( ! DEPLOY_OK )); then
  warn "Stopping before the old token is deleted, so deploys can still be rescued."
  note "Re-run this wizard once the deploy passes. It picks up from here."
  exit 1
fi
pause

# ── Stage 5: retire the old token ─────────────────────────────────────────
stage "Cloudflare: delete the old token"
OLD_CF_TOKEN_ID=""
if [[ -n "$OLD_CF_TOKEN" ]]; then
  OLD_CF_TOKEN_ID=$(cf_first_id "$OLD_CF_TOKEN" "/user/tokens/verify" || true)
fi
open_url "$CF_TOKENS_URL"
step "Find the token Pinch used before. It is NOT 'pinch-share-worker-deploy'."
if [[ -n "$OLD_CF_TOKEN_ID" ]]; then
  note "Its ID is $OLD_CF_TOKEN_ID"
  note "Click a token's '…' → Edit: the ID is the last part of the page address."
fi
step "Delete it: '…' → Delete."
step "If GitHub held a different, older Pinch token, delete that one too."
warn "Leave the R2 token of the micro-content projects alone (zoa-microbe-media-bucket)."
note "It may sit in this same list. Deleting it breaks their uploads."
if [[ -n "$OLD_CF_TOKEN" ]]; then
  while true; do
    confirm "Old token deleted?" || { SKIPPED+=("Delete the old Cloudflare token (ID ${OLD_CF_TOKEN_ID:-unknown})"); break; }
    if cf_ok "$OLD_CF_TOKEN" "/user/tokens/verify"; then
      warn "The old token still works. A different token was deleted, or none was."
    else
      printf '  %s✓%s the old token is dead\n' "$GREEN" "$RESET"
      break
    fi
  done
else
  confirm "Old token(s) deleted?" || SKIPPED+=("Delete the old Cloudflare token Pinch used")
fi
note "Then: set PIN-47 to Done and delete scripts/pin-47-scope-cloudflare-token.sh."
pause

finish
}

run_wizard "$@"; exit
